  assert.ok(P.DUR.flipOn !== P.DUR.drapeOn, "not Vesper's smoke rise");
  assert.ok(P.DUR.flipOn !== P.DUR.flattenOn, "not Sol's pane climb");
  assert.ok(P.DUR.flipOn !== P.DUR.baskOn, "not Ink's paddle");
