  assert.ok(P.DUR.flip !== P.DUR.inspect, "not Bandit's ruler");
  assert.ok(P.DUR.flip !== P.DUR.write, "not Saffron's S-curve");
  assert.ok(P.DUR.flip !== P.DUR.bun, "not Nori's bun hold");
  assert.ok(P.DUR.flip !== P.DUR.kindle, "not Ember's rise");
