  assert.ok(Math.abs(hold.lift - ball.lift) > 20, "not Burr's pane foot");
  assert.ok(Math.abs(hold.x - dust.x) > 20 || Math.abs(hold.lift - dust.lift) > 20, "not Floss's dust tray");
