  assert.ok(P.DUR.open !== P.DUR.gold);
  assert.ok(P.DUR.open !== P.DUR.unfurl);
  assert.ok(P.DUR.open !== P.DUR.lean);
  assert.ok(P.DUR.open !== P.DUR.circle);
  assert.ok(P.DUR.open !== P.DUR.chime);
