  assert.ok(P.DUR.lickHold !== P.DUR.tendHold);
  assert.ok(P.DUR.lickHold !== P.DUR.snipHold);
  assert.ok(P.DUR.lickHold !== P.DUR.daubHold);
  assert.ok(P.DUR.lickHold !== P.DUR.boreHold);
