  assert.ok(P.DUR.drawOn !== P.DUR.layOn);
  assert.ok(P.DUR.drawOn !== P.DUR.droneOn);
  assert.ok(P.DUR.drawOn !== P.DUR.digOn);
  assert.ok(P.DUR.drawOn !== P.DUR.lickOn);
  assert.ok(P.DUR.drawOn !== P.DUR.tendOn);
