  assert.ok(Math.abs(target.holdX - chart.x) > 20 || Math.abs(target.holdLift - chart.lift) > 16, "not Atlas");
  assert.ok(Math.abs(target.holdX - circle.x) > 20 || Math.abs(target.holdLift - circle.lift) > 16, "not Coin");
