  assert.ok(Math.abs(still.x) < 2, "not yet");
  assert.ok(Math.abs(still.lift) < 2, "the first cell is the attach");
  assert.ok(step.x > 8, "a hex neighbor, not Keep's line");
  assert.ok(step.lift < -8, "the neighbor is down the pane");
  assert.ok(down.lift < -16, "hex cells walk down, not a hover");
  assert.ok(after.x > 12, "the sheet stays drawn");
  assert.ok(after.lift < -28, "the body of the comb is below the head");
  const hold = P.drawHoldPath(0.5);
  assert.ok(hold.x > 12, "it remains in the sheet, not back on Keep's heart");
  assert.ok(hold.lift < -28, "the house holds the drawn cells");
  const off0 = P.drawOffPath(0, { x: frame.x, lift: frame.lift }, { x: frame.x + 40, lift: 0 });
