  assert.ok(P.DUR.glueOn !== P.DUR.sillHop);
  assert.ok(P.DUR.glue !== P.DUR.drink);
  assert.ok(P.DUR.glue !== P.DUR.filter);
  assert.ok(P.DUR.glue !== P.DUR.rasp);
  assert.ok(P.DUR.glue !== P.DUR.claw);
  assert.ok(P.DUR.glue !== P.DUR.ring);
  assert.ok(P.DUR.glue !== P.DUR.cover);
