  const lift = P.knobPoint(WIN, P.SPRITE, WORK);
  const latch = P.lidPoint(WIN, P.SPRITE, WORK);
  const rail = P.dustPoint(WIN, P.SPRITE, WORK);
  const hitch = P.hitchPoint(WIN, P.SPRITE, WORK);
  assert.ok(Math.abs(fillet.x - drip.x) > 20 || Math.abs(fillet.lift - drip.lift) > 12, "not Latch");
