  assert.ok(Math.abs(fillet.x - rail.x) > 20 || Math.abs(fillet.lift - rail.lift) > 12, "not Floss");
  assert.ok(Math.abs(fillet.x - hitch.x) > 20 || Math.abs(fillet.lift - hitch.lift) > 12, "not Anchor");
  const dart = P.glueOnPath(0.5, { x: 40, lift: 0 }, { x: fillet.x, lift: fillet.lift });
