  const pressOn = P.glueOnPath(0.92, { x: 40, lift: 0 }, { x: fillet.x, lift: fillet.lift });
  assert.ok(pressOn.lift < fillet.lift - 1, "she presses the nest into the putty");
  const bury = P.filterOnPath(0.5, { x: 40, lift: 0 }, { x: bed.x, lift: bed.lift });
  const loop = P.drinkOnPath(0.5, { x: 40, lift: 0 }, { x: drip.x, lift: drip.lift });
  const pinchWalk = P.clawOnPath(0.5, { x: 40, lift: 0 }, { x: wash.x, lift: wash.lift });
