  assert.ok(glued.lift < drunk.lift - 6, "a press, not a swell");
  assert.ok(Math.abs(glued.x) < 3, "the weave closes; Coin still circles");
  assert.ok(Math.abs(circled.x - fillet.x) > 20 || Math.abs(circled.lift - fillet.lift) > 12, "not Coin's bowl");
