  const chart0 = P.chartPoint(WIN, 0, P.SPRITE, WORK);
  const ledge = P.ledgePoint(WIN, P.SPRITE, WORK);
  const perch = P.perchPoint(WIN, "left", P.SPRITE, WORK);
