  assert.ok(Math.abs(off0.x - rafter.x) < 2);
  assert.ok(offHop.lift > 20, "she hops off the rafter");
  assert.ok(Math.abs(off1.lift) < 2);
  let play = P.beginPlay(target, target.approachX);
  const seen = new Set();
